const contractText = $input.first().json.choices[0].message.content;
const fields = $input.first().json;

const lines = contractText.split('\n');
let htmlBody = '';
let currentSection = '';
let inList = false;

function flushSection() {
  if (inList) {
    currentSection += '</ul>';
    inList = false;
  }
  if (currentSection) {
    htmlBody += '<div style="display:inline-block;width:100%;">' + currentSection + '</div>';
    currentSection = '';
  }
}

for (let i = 0; i < lines.length; i++) {
  const t = lines[i].trim();

  if (!t) {
    if (currentSection) {
      currentSection += '<div style="margin:10px 0"></div>';
    } else {
      htmlBody += '<div style="margin:10px 0"></div>';
    }
    continue;
  }

  const cleaned = t.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\*(.*?)\*/g, '<em>$1</em>');

  const isHeading = t.match(/^\d+\.\s/) || (t.length < 40 && t.split(' ').length <= 4 && !t.includes(':'));
  const isList = t.startsWith('- ') || t.startsWith('* ');
  const isDivider = t.match(/^_{3,}$/);

  if (isHeading) {
    flushSection();
    currentSection = '<h2 style="font-size:13px;font-weight:700;color:#111;margin-top:28px;margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid #eee">' + cleaned + '</h2>';
  } else if (isList) {
    if (!inList) {
      currentSection += '<ul style="margin:0;padding-left:20px">';
      inList = true;
    }
    currentSection += '<li style="margin:6px 0;color:#444;font-size:14px;line-height:1.7">' + cleaned.slice(2) + '</li>';
  } else if (isDivider) {
    if (inList) {
      currentSection += '</ul>';
      inList = false;
    }
    currentSection += '<div style="border-bottom:1px solid #111;margin:16px 0;height:24px;width:200px"></div>';
  } else {
    if (inList) {
      currentSection += '</ul>';
      inList = false;
    }
    currentSection += '<p style="margin:8px 0;color:#444;font-size:14px;line-height:1.7">' + cleaned + '</p>';
  }
}

flushSection();

const header = '<div style="border-bottom:2px solid #111;padding-bottom:28px;margin-bottom:36px">'
  + '<p style="font-size:10px;font-weight:700;letter-spacing:4px;text-transform:uppercase;color:#999;margin-bottom:16px">FREELANCE SERVICE CONTRACT</p>'
  + '<h1 style="font-size:32px;font-weight:400;margin-bottom:12px">' + fields.project_name + '</h1>'
  + '<p style="color:#999;font-size:13px">Between <strong style="color:#111">' + fields.freelancer_name + '</strong> and <strong style="color:#111">' + fields.client_name + (fields.client_company ? ' (' + fields.client_company + ')' : '') + '</strong></p>'
  + '<p style="color:#999;font-size:13px;margin-top:4px">Dated: ' + fields.contract_date + '</p>'
  + '</div>';
const footer = '<hr style="border:none;border-top:1px solid #eee;margin-top:40px;margin-bottom:16px">';
const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body>'
  + '<div style="font-family:Georgia,serif;max-width:780px;margin:0 auto;padding:56px;color:#111">'
  + header
  + htmlBody
  + footer
  + '</div></body></html>';

return [{
  json: {
    html: html,
    freelancer_email: fields.freelancer_email,
    freelancer_name: fields.freelancer_name,
    client_name: fields.client_name,
    client_email: fields.client_email,
    freelancer_service: fields.freelancer_service,
    project_name: fields.project_name,
    amount: fields.amount,
    contract_date: fields.contract_date,
    start_date: fields.start_date,
    end_date: fields.end_date
  }
}];

